<script setup lang="ts">
import { reactive,ref } from 'vue'
import { useRouter } from 'vue-router'
import { api,errorText } from '../api'
import { useRequestKey } from '../composables'
import type { Target } from '../types'
import AppIcon from '../components/AppIcon.vue'
const router=useRouter(),key=useRequestKey(),busy=ref(false),error=ref('')
const form=reactive({code:'',name:'',environment:'development',baseUrl:'',ownerTeam:'',allowHttp:false,cidrs:'',networkReason:''})
async function save(){busy.value=true;error.value='';const body={code:form.code.trim(),name:form.name.trim(),environment:form.environment.trim(),baseUrl:form.baseUrl.trim(),ownerTeam:form.ownerTeam.trim()||null,allowHttp:form.allowHttp,allowedPrivateCidrs:form.cidrs.split(/[,\n]/).map(s=>s.trim()).filter(Boolean),networkReason:form.networkReason.trim()||null};try{const target=await api<Target>('/targets',{method:'POST',body,key:key.forBody(body)});key.clear();await router.push('/targets/'+target.id)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><RouterLink to="/targets" class="back-link"><AppIcon name="arrow" :size="16" />服务目标</RouterLink><div class="page-heading"><div><h1>登记服务目标</h1><p>先登记目标与网络访问策略，再配置健康检查。</p></div></div><form class="panel form-panel" @submit.prevent="save"><div v-if="error" class="error-message" role="alert">{{ error }}</div><h2>服务信息</h2><div class="form-grid"><label>服务名称<input v-model="form.name" required maxlength="160" placeholder="例如：订单服务"></label><label>目标标识<input v-model="form.code" required maxlength="80" pattern="[a-z][a-z0-9-]{0,79}" placeholder="例如：orders-api"><small>小写字母开头，可包含数字和连字符。</small></label><label>环境<input v-model="form.environment" required maxlength="40" placeholder="production / staging / development"></label><label>负责人团队<span class="optional">选填</span><input v-model="form.ownerTeam" maxlength="120" placeholder="例如：平台工程"></label><label class="span-2">健康检查地址<input v-model="form.baseUrl" required type="url" maxlength="2048" placeholder="https://health.example.com/health"><small>使用域名和标准 80/443 端口；不接受账号信息、查询参数或重定向。</small></label></div><div class="form-section"><h2>网络访问批准</h2><label class="check-label"><input v-model="form.allowHttp" type="checkbox">批准此目标使用 HTTP 明文连接</label><label>允许的私网 CIDR<span class="optional">选填</span><textarea v-model="form.cidrs" rows="2" placeholder="每行一个，例如 10.20.1.0/24"></textarea><small>留空时仅允许公网。私网范围还必须在部署侧允许的出站网段内。</small></label><label>批准理由<span v-if="!form.allowHttp&&!form.cidrs.trim()" class="optional">选填</span><textarea v-model="form.networkReason" :required="form.allowHttp||!!form.cidrs.trim()" maxlength="500" rows="2" placeholder="说明此地址与网络范围的使用目的"></textarea></label></div><div class="form-actions"><RouterLink to="/targets" class="btn">取消</RouterLink><button class="btn primary" :disabled="busy">{{ busy?'正在登记…':'登记目标' }}<AppIcon name="chevron" :size="16" /></button></div></form></template>
